+const firstNames=['Aderyn','Vael','Mira','Orren','Sable','Ilyra','Thane','Eris','Caelan','Nyra','Riven','Maelis','Darian','Vesper','Kestrel','Eamon','Lysette','Rook','Seren','Alaric','Isolde','Fen','Astra','Bram','Elowen','Corvin','Liora','Tavian','Maren','Sylas','Aveline','Dusk'];
+const lastNames=['Ashford','Blackmere','Dawnwhisper','Thorn','Vey','Holloway','Storme','Wick','Fell','Nightingale','Morrow','Graves','Silverkin','Wolfe','Emberfall','Vale','Crow','Winterborn','Duskwalker','Greymark','Starling','Briar','Moonwell','Redwyne'];
+const epithets=['the Unbroken','of the Veil'];
+const classes=['Warden','Oathblade','Gravecaller','Dusk Archer','Vowkeeper','Rune Witch','Ash Knight','Veil Stalker'];
+const rarities=['COMMON','UNCOMMON','RARE','EPIC','LEGENDARY'];
+const colors=[['#99724f','#45362e','#d1b08a'],['#687a9b','#31394d','#dad0bf'],['#8e5d58','#402c38','#ceb39a'],['#77835e','#353a31','#c5b28a'],['#9b7955','#44352e','#d9c4a0'],['#6f617e','#322b3b','#d5bba0'],['#8c6844','#3d3030','#d3a784'],['#588079','#27393a','#c3b39c']];
+const heroes=[];
+for(let i=0;i<1536;i++){
+ const classIndex=i%classes.length, colorIndex=(Math.floor(i/3)+i%7)%colors.length;
+ const rarity= i<3?['EPIC','RARE','RARE'][i]: i%79===0?'LEGENDARY':i%13===0?'EPIC':i%4===0?'RARE':i%2===0?'UNCOMMON':'COMMON';
+ const hero={id:i,name:`${firstNames[Math.floor(i/48)]} ${lastNames[Math.floor(i/2)%24]} ${epithets[i%2]}`,class:classes[classIndex],rarity,color:colors[colorIndex],level:i<3?[12,11,10][i]:1,maxHp:100+(i%5)*7,hp:100+(i%5)*7,atk:14+(i%9)*2,focus:3,owned:i<3,alive:true}; heroes.push(hero);
+}
+const state={gold:2480,shards:12,vigor:18, wins:0, wave:1, focus:3, selectedEnemy:null, busy:false, auto:false, owned:[0,1,2], inventory:[], enemy:[], battleOver:false};
+let toastTimer;
+const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
+function heroById(id){return heroes[id]}
+function showToast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
+function save(){try{localStorage.setItem('ashen-covenant-save',JSON.stringify({gold:state.gold,shards:state.shards,vigor:state.vigor,wins:state.wins,owned:state.owned,inventory:state.inventory}))}catch(e){}}
+function load(){try{const d=JSON.parse(localStorage.getItem('ashen-covenant-save'));if(d){state.gold=d.gold??state.gold;state.shards=d.shards??state.shards;state.vigor=d.vigor??state.vigor;state.wins=d.wins||0;state.owned=d.owned||state.owned;state.inventory=d.inventory||[];state.owned.forEach(id=>{if(heroes[id])heroes[id].owned=true})}}catch(e){}}
+function setResources(){ $('#gold-count').textContent=state.gold.toLocaleString();$('#shard-count').textContent=state.shards;$('#stamina-count').textContent=state.vigor;$('#collection-count').textContent=(1536-state.owned.length).toLocaleString();$('#nav-count').textContent=state.owned.length.toLocaleString();$('#party-count').textContent=`${state.owned.length} / 5`;$('#power-stat').textContent=state.owned.slice(0,5).reduce((a,id)=>a+heroes[id].atk*10,0).toLocaleString();$('#vigor-stat').textContent=`${state.vigor} / 18`;save()}
+function portraitStyle(h){return `--c1:${h.color[0]};--c2:${h.color[1]};--c3:${h.color[2]}`}
+function makeEnemy(index){const names=['Hollowed Bellkeeper','Drowned Penitent','Abbey Boneguard','Veil-Touched Monk','Sunken Confessor'];return {name:names[(index+state.wins)%names.length],hp:76+state.wins*10,maxHp:76+state.wins*10,atk:9+state.wins*2,alive:true}}
+function resetBattle(){state.enemy=[makeEnemy(0),makeEnemy(1)];state.selectedEnemy=0;state.focus=3;state.battleOver=false;state.busy=false;renderBattle();$('#battle-log').innerHTML='<b>The veil stirs.</b> A band of hollowed sentries bars your way.';$('#turn-label').textContent='YOUR TURN'}
+function renderBattle(){
+ const wrap=$('#battle-characters');if(!wrap)return;const allies=state.owned.slice(0,3).map((id,i)=>heroes[id]);
+ wrap.innerHTML=allies.map((h,i)=>`<div class="combatant ally ${h.hp<=0?'dead':''} ${!h.alive?'dead':''}" data-hero="${h.id}" style="--c1:${h.color[0]};--c2:${h.color[1]};--c3:${h.color[2]}"><div class="halo"></div><div class="figure"><div class="sprite"><div class="cape"></div><div class="body"></div><div class="arm left"></div><div class="arm right"></div><div class="head"></div><div class="hair"></div><div class="weapon"></div></div></div><div class="unit-info"><div class="unit-name">${h.name.split(' ').slice(0,2).join(' ')}</div><div class="unit-role">${h.class.toUpperCase()} · LV ${h.level}</div><div class="hp-track"><div class="hp-fill" style="width:${Math.max(0,h.hp/h.maxHp*100)}%"></div></div><div class="unit-health">${Math.max(0,h.hp)} / ${h.maxHp}</div></div></div>`).join('')+
+ state.enemy.map((e,i)=>`<div class="combatant enemy ${e.alive?'':'dead'} ${state.selectedEnemy===i?'selected':''}" data-enemy="${i}" style="--c1:#967c76;--c2:#322c34;--c3:#887366"><div class="halo"></div><div class="figure"><div class="sprite"><div class="cape"></div><div class="body"></div><div class="arm left"></div><div class="arm right"></div><div class="head"></div><div class="hair"></div><div class="weapon"></div></div></div><div class="unit-info"><div class="unit-name">${e.name}</div><div class="unit-role">HOLLOWED · ABERRANT</div><div class="hp-track"><div class="hp-fill" style="width:${Math.max(0,e.hp/e.maxHp*100)}%"></div></div><div class="unit-health">${Math.max(0,e.hp)} / ${e.maxHp}</div></div></div>`).join('');
+ wrap.querySelectorAll('[data-enemy]').forEach(el=>el.onclick=()=>{const i=+el.dataset.enemy;if(state.enemy[i]?.alive){state.selectedEnemy=i;renderBattle();$('#action-hint').textContent=`${state.enemy[i].name} selected · choose an action`}});
+ $('#wave-tag').textContent=`WAVE ${state.wave} / 3`;$('#skill-label').textContent=`Skill · ${state.focus} focus`;$('#skill-btn').disabled=state.busy||state.battleOver||state.focus<3;$('#attack-btn').disabled=state.busy||state.battleOver;$('#guard-btn').disabled=state.busy||state.battleOver;$('#retreat-btn').disabled=state.busy;
+}
+function renderParty(){const list=$('#party-list');list.innerHTML=state.owned.slice(0,5).map(id=>{const h=heroes[id];return `<div class="party-unit"><div class="mini-portrait" style="${portraitStyle(h)}"></div><div class="party-data"><div class="party-name">${h.name}</div><div class="party-role">${h.class.toUpperCase()} · ${h.rarity}</div></div><span class="party-lv">${h.level}</span></div>`}).join('')}
+function log(text){$('#battle-log').innerHTML=text;}
+function aliveAllies(){return state.owned.slice(0,3).map(id=>heroes[id]).filter(h=>h.hp>0)}
+function selectLivingEnemy(){let i=state.enemy.findIndex(e=>e.alive);if(i<0)i=0;state.selectedEnemy=i;return state.enemy[i]}
+function attack(kind){if(state.busy||state.battleOver)return;let target=state.enemy[state.selectedEnemy];if(!target?.alive)target=selectLivingEnemy();if(!target)return;
+ const active=aliveAllies();if(!active.length){log('<b>Your covenant has fallen.</b> Retreat and return stronger.');state.battleOver=true;renderBattle();return}
+ const attacker=active[state.wins%active.length];state.busy=true;renderBattle();let damage=kind==='skill'?attacker.atk*2+Math.floor(Math.random()*9):kind==='guard'?0:attacker.atk+Math.floor(Math.random()*8);
+ if(kind==='guard'){attacker.hp=Math.min(attacker.maxHp,attacker.hp+24);state.focus=Math.min(6,state.focus+1);log(`<b>${attacker.name.split(' ')[0]} takes a guarded stance.</b> Restored 24 vitality and recovered 1 focus.`)}
+ else {target.hp-=damage;if(target.hp<=0){target.hp=0;target.alive=false;state.gold+=22;state.focus=Math.min(6,state.focus+1);log(`<b>${attacker.name.split(' ')[0]} ${kind==='skill'?'unleashes Oathfire':'strikes'}!</b> ${target.name} falls. +22 gold`)}else log(`<b>${attacker.name.split(' ')[0]} ${kind==='skill'?'calls the oathfire':'lands a strike'}.</b> ${target.name} takes ${damage} damage.`);if(kind==='skill')state.focus=Math.max(0,state.focus-3)}
+ renderBattle();setResources();
+ setTimeout(()=>{if(state.enemy.every(e=>!e.alive)){winWave();return}enemyTurn()},650);
+}
+function enemyTurn(){if(state.battleOver)return;const e=state.enemy.find(e=>e.alive),allies=aliveAllies();if(!e){winWave();return}if(!allies.length){state.battleOver=true;state.busy=false;log('<b>Your covenant has fallen.</b> Retreat to the sanctuary to recover.');renderBattle();return}
+ const target=allies[Math.floor(Math.random()*allies.length)],dmg=e.atk+Math.floor(Math.random()*6);target.hp-=dmg;if(target.hp<0)target.hp=0;log(`<b>${e.name} retaliates.</b> ${target.name.split(' ')[0]} suffers ${dmg} damage.`);state.busy=false;renderBattle();renderParty();setResources();if(!aliveAllies().length){state.battleOver=true;log('<b>Your covenant has fallen.</b> Retreat and return stronger.');renderBattle();return}if(state.auto)setTimeout(()=>attack('strike'),550)
+}
+function winWave(){if(state.wave<3){state.wave++;state.enemy=[makeEnemy(0),makeEnemy(1),...(state.wave===3?[makeEnemy(2)]:[])];state.enemy.forEach(e=>e.hp+=state.wave*15,e.maxHp=e.hp);state.focus=Math.min(6,state.focus+1);state.busy=false;log(`<b>Wave ${state.wave-1} broken.</b> The abbey doors shudder open. Another presence stirs...`);renderBattle();return}state.battleOver=true;state.busy=false;state.wins++;state.gold+=180;state.shards+=2;state.vigor=Math.max(0,state.vigor-2);heroes.forEach(h=>{if(state.owned.includes(h.id)&&h.hp>0)h.hp=Math.min(h.maxHp,h.hp+14)});log('<b>Expedition complete!</b> +180 gold · +2 shards · +40 renown. The Sunken Abbey is silent.');$('#turn-label').textContent='VICTORY';$('#mission-btn').textContent='CLAIM REWARDS · 180 ◈';renderBattle();renderParty();setResources();showToast('Expedition complete · rewards added')}
+function retreat(){if(state.busy)return;state.owned.forEach(id=>{heroes[id].hp=heroes[id].maxHp});state.wave=1;state.vigor=Math.min(18,state.vigor+1);resetBattle();renderParty();setResources();showToast('Retreated to sanctuary · covenant recovered')}

