function openModal(type){const overlay=$('#overlay'),modal=$('#modal-content');overlay.classList.add('open');if(type==='heroes'){modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">THE COVENANT CODEX</div><h2>Souls of the Veil</h2></div><button class="close-btn" data-close>×</button></div><div class="roster-tools"><input id="roster-search" placeholder="Search names, classes, or titles…"><select id="rarity-filter"><option value="">All rarities</option>${rarities.map(r=>`<option>${r}</option>`).join('')}</select><select id="class-filter"><option value="">All callings</option>${classes.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="roster-grid" id="roster-grid"></div><div class="roster-footer"><span id="roster-status"></span><div><button class="btn" id="roster-prev">← PREV</button> <button class="btn" id="roster-next">NEXT →</button></div></div>`;renderRoster(0)}else if(type==='summon'){modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">THE VEIL BETWEEN WORLDS</div><h2>Call a wandering soul</h2></div><button class="close-btn" data-close>×</button></div><div class="summon-content"><div class="summon-orb">✧</div><h3>Echoes of the Covenant</h3><p>Every soul is singular, with a name, calling, and colors of their own. The Codex holds <b style="color:#ddc898">1,536 distinct wanderers</b> waiting beyond the veil. Your call draws one soul you have yet to meet.</p><div class="summon-bottom"><button class="btn gold" id="summon-shards">✦ &nbsp; CALL WITH 3 SHARDS</button><button class="btn" id="summon-gold">◈ &nbsp; CALL WITH 400 GOLD</button></div><div class="summon-result" id="summon-result"></div></div>`;$('#summon-shards').onclick=()=>summon('shards');$('#summon-gold').onclick=()=>summon('gold')}else{const pages={codex:['The Chronicle','Fragments of a world fading at the edges.','The first covenant swore their oath beneath a starless sky. They were not the first to hear the Veil sing, but they would be the last to answer.'],map:['The Veiled Marches','A realm on the edge of remembrance.','Explore the drowned abbey and follow the old pilgrimage road. Complete expeditions to reveal what lies beyond the Marches.'],guild:['The Covenant','No oath is kept alone.','Your covenant is small, but the Veil is wide. Gather heroes from every corner of the realm and shape your own legend.']};const [title,sub,copy]=pages[type]||pages.codex;modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">ASHEN COVENANT · ARCHIVES</div><h2>${title}</h2></div><button class="close-btn" data-close>×</button></div><div style="padding:16px 3px 22px;text-align:center"><div class="summon-orb" style="font-size:36px">${type==='map'?'⌖':type==='guild'?'♜':'▤'}</div><h3 style="font:20px var(--serif);font-weight:400">${sub}</h3><p style="color:#aaa2a0;line-height:1.7;max-width:470px;margin:10px auto 20px">${copy}</p><button class="btn gold" data-close>RETURN TO CAMPAIGN</button></div>`}
