function closeModal(){$('#overlay').classList.remove('open');document.onkeydown=null}
let rosterPage=0;
function renderRoster(page){rosterPage=page;const query=($('#roster-search')?.value||'').toLowerCase(),rarity=$('#rarity-filter')?.value||'',cls=$('#class-filter')?.value||'';const filtered=heroes.filter(h=>(!query||`${h.name} ${h.class} ${h.rarity}`.toLowerCase().includes(query))&&(!rarity||h.rarity===rarity)&&(!cls||h.class===cls));const per=24,pages=Math.max(1,Math.ceil(filtered.length/per));rosterPage=Math.min(Math.max(0,page),pages-1);const grid=$('#roster-grid');grid.innerHTML=filtered.slice(rosterPage*per,(rosterPage+1)*per).map(h=>`<button class="roster-card" data-id="${h.id}" title="${h.owned?'In your covenant':'Not yet found'}"><div class="mini-portrait" style="${portraitStyle(h)}"></div><div class="roster-meta"><b>${h.name}</b><small><span class="rarity">${h.rarity}</span> · ${h.class}${h.owned?' · <span style="color:#8eae84">OWNED</span>':''}</small></div></button>`).join('')||'<div class="empty-state">No souls answer that description.</div>';$('#roster-status').textContent=`${filtered.length.toLocaleString()} souls · page ${rosterPage+1} of ${pages}`;$('#roster-prev').disabled=rosterPage===0;$('#roster-next').disabled=rosterPage>=pages-1;$('#roster-prev').onclick=()=>renderRoster(rosterPage-1);$('#roster-next').onclick=()=>renderRoster(rosterPage+1);$('#roster-search').oninput=()=>renderRoster(0);$('#rarity-filter').onchange=()=>renderRoster(0);$('#class-filter').onchange=()=>renderRoster(0);grid.querySelectorAll('[data-id]').forEach(card=>card.onclick=()=>{const h=heroes[+card.dataset.id];if(h.owned){showToast(`${h.name} · ${h.class} · Level ${h.level}`)}else showToast(`${h.name} awaits beyond the veil`)})}
function summon(currency){if(currency==='shards'&&state.shards<3){showToast('You need 3 shards for a call');return}if(currency==='gold'&&state.gold<400){showToast('You need 400 gold for a call');return}if(currency==='shards')state.shards-=3;else state.gold-=400;const unowned=heroes.filter(h=>!h.owned);if(!unowned.length){state.shards+=currency==='shards'?3:0;state.gold+=currency==='gold'?400:0;showToast('Every soul in the Codex has answered!');return}const h=unowned[Math.floor(Math.random()*unowned.length)];h.owned=true;h.hp=h.maxHp;state.owned.push(h.id);setResources();renderParty();const result=$('#summon-result');result.innerHTML=`<div class="result-art" style="${portraitStyle(h)}"></div><div class="result-copy"><small>${h.rarity} · ${h.class}</small><b>${h.name}</b><small>Level 1 · A new soul joins your covenant</small></div>`;result.classList.add('show');showToast(`${h.name} answered your call`)}
function navigate(which){if(which==='heroes'){openModal('heroes');return}if(which==='summon'){openModal('summon');return}if(which==='battle'){closeModal();return}if(which==='codex'||which==='map'||which==='guild'){openModal(which);return}showToast('The Veiled Marches await your next chapter')}

